import React, { useState } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send } from 'lucide-react';
import { CheckType, AttendancePayload, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
