  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);

  const handleSubmit = async () => {
    setIsSubmitting(true);

    // Logic Phase: Randomize timestamp
    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    const payload: AttendancePayload = {
      userID,
      typeCheckInOut: type,
      dateCheckInOut: formattedDate
    };

    // Simulate API Call
    console.log("%c[API PAYLOAD SENT]", "color: #4f46e5; font-weight: bold", payload);
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Success State
    const newLog: LogEntry = {
      ...payload,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev].slice(0, 5));
    setLastSubmission({ time: randomTime, type });
    setIsSubmitting(false);

    // Reset last submission alert after 5 seconds
    setTimeout(() => setLastSubmission(null), 5000);
  };

  return (
