                    }`}
                  >
                    Check-in
                  </button>
                  <button
                    onClick={() => setType(CheckType.OUT)}
                    className={`py-3.5 rounded-xl font-semibold transition-all duration-200 ${
                      type === CheckType.OUT 
                        ? 'bg-white text-indigo-600 shadow-sm' 
                        : 'text-slate-500 hover:text-slate-700'
                    }`}
                  >
