      <form onSubmit={handleLogin} className="space-y-5 text-left">
        {/* Nhập Tên Tài Khoản */}
        <div className="space-y-2">
          <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Tên tài khoản</label>
          <div className="relative">
            <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input
              type="text"
              placeholder="Nhập tên tài khoản..."
              value={accountName}
              onChange={(e) => setAccountName(e.target.value)}
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border border-slate-200 text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
              required
            />
          </div>
        </div>

        {/* Nhập User ID */}
        <div className="space-y-2">
          <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Mã nhân viên (User ID)</label>
          <div className="relative">
            <Shield className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
            <input
              type="text"
              placeholder="Ví dụ: EMP-9988"
              value={inputUserID}
              onChange={(e) => setInputUserID(e.target.value)}
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border border-slate-200 text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
              required
            />
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full mt-4 py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-400 text-white font-semibold rounded-2xl flex items-center justify-center gap-3 transition-all duration-200 active:scale-95 shadow-lg shadow-indigo-100"
        >
          {isLoading ? (
            <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin" />
          ) : (
            <>
              <LogIn className="w-5 h-5" />
              Đăng nhập ngay
            </>
          )}
        </button>
      </form>

      <div className="mt-8 pt-6 border-t border-slate-50 flex items-center justify-center gap-2 text-xs text-slate-400">
        <span className="w-2 h-2 bg-green-500 rounded-full"></span>
        Hệ thống đang hoạt động ổn định
      </div>
    </div>
  );
};

