  userID: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const dateInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = async () => {
    setIsSubmitting(true);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    const payload: AttendancePayload = {
      userID,
      typeCheckInOut: type,
      dateCheckInOut: formattedDate
    };

    console.log("%c[DỮ LIỆU API ĐÃ GỬI]", "color: #4f46e5; font-weight: bold", payload);
    await new Promise(resolve => setTimeout(resolve, 1000));

    const newLog: LogEntry = {
      ...payload,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev].slice(0, 5));
    setLastSubmission({ time: randomTime, type });
    setIsSubmitting(false);

    setTimeout(() => setLastSubmission(null), 5000);
  };

  const openDatePicker = () => {
    if (dateInputRef.current) {
      try {
        (dateInputRef.current as any).showPicker();
      } catch (e) {
        dateInputRef.current.focus();
      }
    }
  };

  return (
    <div className="w-full max-w-3xl flex flex-col gap-5 animate-in fade-in slide-in-from-bottom-8 duration-700 ease-out">
      {/* Thông tin Header */}
      <div className="flex flex-col md:flex-row items-center justify-between bg-white rounded-2xl p-4 shadow-lg shadow-slate-200/50 border border-slate-50 gap-4 transition-all hover:shadow-xl">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 bg-gradient-to-br from-indigo-500 to-blue-600 rounded-xl flex items-center justify-center shadow-md shadow-indigo-100">
            <User className="text-white w-5 h-5" />
          </div>
          <div className="text-left">
            <h2 className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">ID hiện tại</h2>
            <p className="text-lg font-extrabold text-slate-800 tracking-tight leading-none">{userID}</p>
          </div>
        </div>
        <button 
          onClick={onLogout}
          className="px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 text-sm font-bold rounded-xl transition-all duration-300 flex items-center gap-2 active:scale-95 border border-transparent hover:border-red-100"
        >
          <LogOut className="w-4 h-4" />
          Đăng xuất
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-5">
        {/* Điều khiển chính */}
        <div className="lg:col-span-3 space-y-5">
          <div className="bg-white rounded-[1.5rem] p-6 shadow-lg shadow-slate-200/50 border border-slate-50">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2">
              <Clock className="w-5 h-5 text-indigo-600" />
              Chấm công
            </h3>

            <div className="space-y-6 text-left">
              {/* Chọn ngày */}
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 ml-1 uppercase tracking-wide">Chọn ngày làm việc</label>
                <div onClick={openDatePicker} className="group relative cursor-pointer">
                  <div className="absolute left-3.5 top-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-lg flex items-center justify-center border border-slate-100 shadow-sm group-hover:scale-105 transition-transform duration-300">
                    <Calendar className="w-4 h-4 text-blue-500" />
                  </div>
                  <input 
                    ref={dateInputRef}
                    type="date"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    className="w-full pl-14 pr-4 py-3 rounded-xl bg-slate-50 border-2 border-slate-50 text-slate-900 font-bold text-base focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 focus:bg-white transition-all appearance-none cursor-pointer"
                  />
                </div>
              </div>

              {/* Lựa chọn loại chấm công */}
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 ml-1 uppercase tracking-wide">Hình thức ghi nhận</label>
                <div className="relative flex p-1 bg-slate-100 rounded-xl border border-slate-200">
                  <div 
                    className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-lg shadow-sm transition-all duration-400 ease-out z-0 ${
                      type === CheckType.OUT ? 'translate-x-full' : 'translate-x-0'
                    }`}
                  />
                  <button
                    onClick={() => setType(CheckType.IN)}
                    className={`relative z-10 flex-1 py-2.5 rounded-lg font-bold text-sm transition-colors duration-300 active:scale-95 ${
                      type === CheckType.IN ? 'text-indigo-600' : 'text-slate-400'
                    }`}
                  >
                    Check-in
                  </button>
                  <button
                    onClick={() => setType(CheckType.OUT)}
                    className={`relative z-10 flex-1 py-2.5 rounded-lg font-bold text-sm transition-colors duration-300 active:scale-95 ${
                      type === CheckType.OUT ? 'text-indigo-600' : 'text-slate-400'
                    }`}
                  >
                    Check-out
                  </button>
                </div>
              </div>

              {/* Thông báo thành công */}
              {lastSubmission && (
                <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4 flex items-start gap-3 animate-in slide-in-from-top-2 fade-in duration-400 shadow-sm">
                  <CheckCircle2 className="text-emerald-500 w-5 h-5 flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="text-xs font-bold text-emerald-900">Gửi thành công!</p>
                    <p className="text-[11px] text-emerald-700/80">
                      Hệ thống ghi nhận lúc: <span className="font-black text-emerald-600">{lastSubmission.time}</span>
                    </p>
                  </div>
                </div>
              )}

              {/* Nút gửi */}
              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="group relative w-full overflow-hidden py-3.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-black text-sm rounded-xl shadow-lg shadow-indigo-100 transition-all duration-300 active:scale-[0.98]"
              >
                <div className="relative z-10 flex items-center justify-center gap-2">
                  {isSubmitting ? (
                    <div className="w-5 h-5 border-[3px] border-white/30 border-t-white rounded-full animate-spin" />
                  ) : (
                    <>
                      <Send className="w-4 h-4 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
                      XÁC NHẬN CHẤM CÔNG
                    </>
                  )}
                </div>
              </button>
            </div>
          </div>
        </div>

        {/* Bảng lịch sử */}
        <div className="lg:col-span-2 space-y-5">
          <div className="bg-white rounded-[1.5rem] p-6 shadow-lg shadow-slate-200/50 border border-slate-50 h-full flex flex-col">
            <h3 className="text-lg font-black text-slate-800 mb-5 flex items-center gap-2">
              <History className="w-5 h-5 text-indigo-500" />
              Lịch sử
            </h3>

            <div className="space-y-3 flex-1 overflow-y-auto max-h-[400px] pr-1 custom-scrollbar">
              {logs.length === 0 ? (
                <div className="text-center py-12 opacity-30">
                  <History className="text-slate-300 w-10 h-10 mx-auto mb-2" />
                  <p className="text-[11px] font-bold text-slate-400">Trống</p>
                </div>
              ) : (
                logs.map((log, index) => (
                  <div 
                    key={log.id} 
                    className="p-3.5 rounded-xl bg-slate-50 border border-slate-100 hover:border-indigo-100 hover:bg-white transition-all duration-300 text-left animate-in fade-in slide-in-from-right-4 shadow-sm hover:shadow-md"
                    style={{ animationDelay: `${index * 80}ms`, animationFillMode: 'both' }}
                  >
                    <div className="flex justify-between items-center mb-2">
                      <div className={`flex items-center gap-1.5 px-2 py-0.5 rounded-md ${
                        log.typeCheckInOut === CheckType.IN 
                          ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' 
                          : 'bg-amber-50 text-amber-700 border border-amber-100'
                      }`}>
                        <div className={`w-1.5 h-1.5 rounded-full ${log.typeCheckInOut === CheckType.IN ? 'bg-indigo-500' : 'bg-amber-500'}`} />
                        <span className="text-[9px] font-black uppercase tracking-tighter">
                          {log.typeCheckInOut === CheckType.IN ? 'Check-in' : 'Check-out'}
                        </span>
                      </div>
                      <span className="text-[9px] text-slate-400 font-bold">
                        {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true })}
                      </span>
                    </div>
                    <div className="space-y-0.5">
                      <p className="text-xs font-bold text-slate-700 font-mono tracking-tighter overflow-hidden text-ellipsis whitespace-nowrap">
                        {log.dateCheckInOut}
                      </p>
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="mt-6 pt-6 border-t border-slate-100 text-left">
               <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Quy định</h4>
               <div className="grid grid-cols-1 gap-2">
                 <div className="px-3 py-2 rounded-lg bg-indigo-50/50 flex justify-between items-center">
                    <span className="text-[10px] font-bold text-indigo-800">Check-in</span>
                    <span className="text-[10px] font-medium text-indigo-600">08:13 - 08:29</span>
                 </div>
                 <div className="px-3 py-2 rounded-lg bg-amber-50/50 flex justify-between items-center">
                    <span className="text-[10px] font-bold text-amber-800">Check-out</span>
                    <span className="text-[10px] font-medium text-amber-600">17:33 - 18:14</span>
                 </div>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

