import React, { useState, useRef } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send, Clock } from 'lucide-react';
import { CheckType, AttendancePayload, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const dateInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = async () => {
    setIsSubmitting(true);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    const payload: AttendancePayload = {
      userID,
      typeCheckInOut: type,
      dateCheckInOut: formattedDate
    };

    console.log("%c[DỮ LIỆU API ĐÃ GỬI]", "color: #4f46e5; font-weight: bold", payload);
    await new Promise(resolve => setTimeout(resolve, 1000));

    const newLog: LogEntry = {
      ...payload,
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now()
    };

    setLogs(prev => [newLog, ...prev].slice(0, 5));
    setLastSubmission({ time: randomTime, type });
    setIsSubmitting(false);

    setTimeout(() => setLastSubmission(null), 5000);
  };

  const openDatePicker = () => {
    if (dateInputRef.current) {
      try {
        // Sử dụng phương thức showPicker hiện đại
        (dateInputRef.current as any).showPicker();
      } catch (e) {
        dateInputRef.current.focus();
        dateInputRef.current.click();
      }
    }
  };

  // Định dạng ngày hiển thị từ YYYY-MM-DD sang DD-MM-YYYY
  const displayDate = () => {
    const [y, m, d] = selectedDate.split('-');
    return `${d}-${m}-${y}`;
  };

  return (
