  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);

  // Settings state
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [basicAuth, setBasicAuth] = useState('');
  const [accessToken, setAccessToken] = useState('');

  // Load settings from localStorage on mount
  useEffect(() => {
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
    alert('Đã lưu cấu hình bảo mật!');
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    const payload: AttendancePayload = {
      userID,
      typeCheckInOut: type,
      dateCheckInOut: formattedDate
    };

    try {
      // Gọi qua Proxy Server (BFF)
      const response = await fetch('/proxy/checkin', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          // Gửi kèm credentials từ localStorage nếu server proxy cần dùng của user thay vì env
          'x-client-basic': basicAuth,
          'x-client-token': accessToken
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) throw new Error('Proxy error');

      const result = await response.json();
      console.log("[Proxy Response]:", result);

      const newLog: LogEntry = {
        ...payload,
        id: Math.random().toString(36).substr(2, 9),
        timestamp: Date.now()
      };

      setLogs(prev => [newLog, ...prev].slice(0, 5));
      setLastSubmission({ time: randomTime, type });
