const express = require('express');
const axios = require('axios');
const path = require('path');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3001;

app.use(express.json());

// Proxy endpoint
app.post('/proxy/checkin', async (req, res) => {
  try {
    const { userID, typeCheckInOut, dateCheckInOut } = req.body;

    // Lấy credentials từ env (Ưu tiên bảo mật server)
    // Nếu không có trong env, có thể lấy từ header client gửi lên (tùy nhu cầu)
    const basicAuth = process.env.BASIC_AUTH || req.headers['x-client-basic'];
    const accessToken = process.env.ACCESS_TOKEN || req.headers['x-client-token'];

    if (!basicAuth || !accessToken) {
      return res.status(401).json({ error: 'Missing credentials. Set them in .env or UI Settings.' });
    }

    console.log(`[BFF Proxy] Forwarding check-in for User: ${userID}, Type: ${typeCheckInOut}`);

    // Call REAL API
    // Giả sử URL API thật của bạn ở đây
    const REAL_API_URL = 'https://api.yourcompany.com/attendance/checkin';

    const response = await axios.post(REAL_API_URL, {
      userID,
      typeCheckInOut,
      dateCheckInOut
    }, {
      headers: {
        'Authorization': `Basic ${basicAuth}`,
        'x-access-token': accessToken,
        'Content-Type': 'application/json'
      }
    });

    // Trả về kết quả cho React client
    res.status(200).json(response.data);

  } catch (error) {
    console.error('[BFF Proxy Error]:', error.message);

    // Fallback: Nếu API thật chưa có, ta trả về mock success cho demo
    if (process.env.NODE_ENV !== 'production') {
      return res.status(200).json({ 
        status: 'success', 
        message: 'Mock response from Proxy (Real API not reached)',
        received: req.body 
      });
    }

    res.status(error.response?.status || 500).json({
      error: 'Proxy failed to forward request',
      details: error.message
    });
  }
});

