    try {
      // LOG ĐỂ KIỂM TRA (Sẽ thấy credentials gửi trực tiếp từ client)
      console.log("%c[GỬI TRỰC TIẾP API]", "color: #10b981; font-weight: bold", {
        url: 'https://api.yourcompany.com/attendance/checkin', // Thay bằng URL thật của bạn
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'x-access-token': accessToken
