              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Access Token</label>
                <textarea
                  placeholder="Nhập Token của bạn..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-mono text-xs h-24 resize-none"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg active:scale-95 shadow-indigo-100"
              >
                <Save className="w-4 h-4" />
                LƯU VÀO TRÌNH DUYỆT
              </button>
              <div className="flex items-center gap-2 justify-center py-2 bg-amber-50 rounded-xl border border-amber-100">
                <ShieldCheck className="w-3.5 h-3.5 text-amber-500" />
                <p className="text-[10px] text-amber-700 font-medium">Lưu ý: Dữ liệu chỉ nằm tại máy này.</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row items-center justify-between bg-white rounded-2xl p-4 shadow-lg shadow-slate-200/50 border border-slate-50 gap-4 transition-all hover:shadow-xl">
