            title="Cài đặt API"
          >
            <Settings className="w-5 h-5" />
          </button>
          <div className="w-px h-6 bg-slate-100 mx-1"></div>
          <button 
            onClick={onLogout}
            className="px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 text-sm font-bold rounded-xl transition-all duration-300 flex items-center gap-2 active:scale-95 border border-transparent hover:border-red-100"
          >
            <LogOut className="w-4 h-4" />
