                    </p>
                  </div>
                </div>
              )}

              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="group relative w-full overflow-hidden py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-black text-sm rounded-xl shadow-lg shadow-indigo-100 transition-all duration-300 active:scale-[0.98]"
              >
