              ) : (
                logs.map((log, index) => (
                  <div key={log.id} className="p-3.5 rounded-xl bg-slate-50 border border-slate-100 hover:border-indigo-100 hover:bg-white transition-all duration-300 text-left animate-in fade-in slide-in-from-right-4 shadow-sm">
