  const handleSubmit = async () => {
    if (!apiUrl || !basicAuth || !accessToken) {
      alert("Vui lòng vào phần Cài đặt để cấu hình URL, Basic Auth và Token!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    // Xây dựng URL với Query Parameters theo yêu cầu
    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
