                  <div>
                    <p className="text-xs font-bold text-emerald-900">Gửi thành công!</p>
                    <p className="text-[11px] text-emerald-700/80">
                      Hệ thống ghi nhận lúc: <span className="font-black text-emerald-600">{lastSubmission.time}</span>
                    </p>
                  </div>
                </div>
              )}

              {errorMessage && (
                <div className="bg-red-50 border border-red-100 rounded-xl p-4 flex items-start gap-3 animate-in slide-in-from-top-2 fade-in duration-400 shadow-sm text-left">
                  <AlertCircle className="text-red-500 w-5 h-5 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs font-bold text-red-900">Gửi thất bại!</p>
                    <p className="text-[11px] text-red-700/80 leading-snug">{errorMessage}</p>
                  </div>
                </div>
              )}

              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="group relative w-full overflow-hidden py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-black text-sm rounded-xl shadow-lg shadow-indigo-100 transition-all duration-300 active:scale-[0.98]"
              >
