  useEffect(() => {
    const savedDomain = localStorage.getItem('sync_api_domain') || '';
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setApiDomain(savedDomain);
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_api_domain', apiDomain);
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
  };

  const handleSubmit = async () => {
    if (!apiDomain || !basicAuth || !accessToken) {
      setErrorMessage("Vui lòng vào phần Cài đặt để cấu hình Domain, Basic Auth và Token!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    setLastSubmission(null);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    // Clean domain and construct full URL
    const cleanDomain = apiDomain.replace(/^https?:\/\//, '').replace(/\/$/, '');
    const targetUrl = `https://${cleanDomain}${API_PATH}`;

    // Query Parameters
    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
    });

    const fullUrl = `${targetUrl}?${params.toString()}`;

    try {
      console.log("%c[GỬI REQUEST API TRỰC TIẾP]", "color: #3b82f6; font-weight: bold", {
        url: fullUrl,
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken
        }
      });

      const response = await fetch(fullUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken,
          'Accept': 'application/json'
        },
        body: ''
      });

      if (!response.ok) {
        throw new Error(`Lỗi HTTP ${response.status}. Kiểm tra Domain/Token.`);
      }

      const result = await response.json();
      console.log("[Kết quả API]:", result);

      // Kiểm tra resultCode: 1 là thành công theo yêu cầu
      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 5));
        setLastSubmission({ time: randomTime, type });
      } else {
        throw new Error(result.message || "Máy chủ phản hồi thất bại.");
      }
    } catch (error) {
      console.error("Lỗi thực thi:", error);

      let msg = error instanceof Error ? error.message : "Đã có lỗi xảy ra.";
      if (msg === "Failed to fetch") {
        msg = "Lỗi kết nối (CORS). Trình duyệt chặn request trực tiếp do chính sách bảo mật, khác với Postman. Hãy kiểm tra cấu hình CORS trên server.";
      }
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-3xl flex flex-col gap-5 animate-in fade-in slide-in-from-bottom-8 duration-700 ease-out relative">

      {/* Settings Panel Overlay */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 duration-300 border border-slate-100 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-6">
              <div className="flex flex-col">
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                  <Settings className="w-6 h-6 text-indigo-600 animate-spin-slow" />
                  Cấu hình Hệ thống
                </h3>
                <span className="text-[10px] text-emerald-500 font-bold uppercase tracking-wider">LƯU TRỮ LOCALSTORAGE</span>
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>

            <div className="space-y-5 text-left">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1">
                  <Link className="w-3 h-3" /> API DOMAIN
                </label>
                <input
                  type="text"
                  placeholder="Ví dụ: apiurl.com"
                  value={apiDomain}
                  onChange={(e) => setApiDomain(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-mono text-xs"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1">
                   AUTHORIZATION HEADER (BASIC)
                </label>
                <input
                  type="password"
                  placeholder="Basic c3NkX2F..."
                  value={basicAuth}
                  onChange={(e) => setBasicAuth(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-mono text-xs"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-1">
                   ACCESS TOKEN (TOKEN HEADER)
                </label>
                <textarea
                  placeholder="eyJhbGci..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-mono text-xs h-32 resize-none"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl flex items-center justify-center gap-2 transition-all shadow-lg active:scale-95 shadow-indigo-100"
              >
                <Save className="w-4 h-4" />
                LƯU CẤU HÌNH
              </button>

              <div className="flex items-center gap-2 justify-center py-2 bg-slate-50 rounded-xl border border-slate-100">
                <ShieldCheck className="w-3.5 h-3.5 text-slate-400" />
                <p className="text-[10px] text-slate-500 font-medium italic">API sẽ được gọi trực tiếp từ trình duyệt</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex flex-col md:flex-row items-center justify-between bg-white rounded-2xl p-4 shadow-lg shadow-slate-200/50 border border-slate-50 gap-4 transition-all hover:shadow-xl">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-gradient-to-br from-indigo-500 to-blue-600 rounded-2xl flex items-center justify-center shadow-md shadow-indigo-100">
            <User className="text-white w-6 h-6" />
          </div>
          <div className="text-left">
            <h2 className="text-lg font-black text-slate-800 leading-tight">{username}</h2>
            <div className="flex items-center gap-1.5">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Mã NV:</span>
              <span className="text-[11px] font-extrabold text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded-md">{userID}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all active:scale-90 border border-transparent hover:border-indigo-100"
            title="Cài đặt API"
          >
            <Settings className="w-5 h-5" />
          </button>
          <div className="w-px h-6 bg-slate-100 mx-1"></div>
          <button 
            onClick={onLogout}
            className="px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 text-sm font-bold rounded-xl transition-all duration-300 flex items-center gap-2 active:scale-95 border border-transparent hover:border-red-100"
          >
            <LogOut className="w-4 h-4" />
            Thoát
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-5">
        <div className="lg:col-span-3 space-y-5 text-left">
          <div className="bg-white rounded-[1.5rem] p-6 shadow-lg shadow-slate-200/50 border border-slate-50">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2">
              <Clock className="w-5 h-5 text-indigo-600" />
              Chấm công
            </h3>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 ml-1 uppercase tracking-wide">Chọn ngày làm việc</label>
                <div className="relative w-full h-[72px] group overflow-hidden cursor-pointer">
                  <div className="absolute inset-0 bg-slate-50 group-hover:bg-white border-2 border-slate-100 group-hover:border-blue-400 rounded-xl transition-all duration-300 shadow-sm flex items-center p-3.5 z-0">
                    <div className="w-10 h-10 bg-blue-500 rounded-lg flex items-center justify-center shadow-md mr-4 group-hover:scale-105 transition-transform">
                      <Calendar className="w-5 h-5 text-white" />
                    </div>
                    <div className="flex flex-col text-left">
                      <span className="text-xs text-slate-400 font-bold uppercase tracking-tight leading-none mb-1">Ngày đã chọn</span>
                      <span className="text-lg font-black text-slate-800 tracking-tight leading-none">{displayDate()}</span>
                    </div>
                  </div>
                  <input 
                    type="date"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                    style={{ colorScheme: 'light' }}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 ml-1 uppercase tracking-wide text-left block">Hình thức ghi nhận</label>
                <div className="relative flex p-1 bg-slate-100 rounded-xl border border-slate-200">
                  <div 
                    className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-lg shadow-sm transition-all duration-400 ease-out z-0 ${
                      type === CheckType.OUT ? 'translate-x-full' : 'translate-x-0'
                    }`}
                  />
                  <button
                    onClick={() => setType(CheckType.IN)}
                    className={`relative z-10 flex-1 py-2.5 rounded-lg font-bold text-sm transition-colors duration-300 active:scale-95 ${
                      type === CheckType.IN ? 'text-indigo-600' : 'text-slate-400'
                    }`}
                  >
                    Check-in
                  </button>
                  <button
                    onClick={() => setType(CheckType.OUT)}
                    className={`relative z-10 flex-1 py-2.5 rounded-lg font-bold text-sm transition-colors duration-300 active:scale-95 ${
                      type === CheckType.OUT ? 'text-indigo-600' : 'text-slate-400'
                    }`}
                  >
                    Check-out
                  </button>
                </div>
              </div>

              {lastSubmission && (
                <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4 flex items-start gap-3 animate-in slide-in-from-top-2 fade-in duration-400 shadow-sm text-left">
                  <CheckCircle2 className="text-emerald-500 w-5 h-5 flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="text-xs font-bold text-emerald-900">Gửi thành công!</p>
                    <p className="text-[11px] text-emerald-700/80">
                      Hệ thống ghi nhận lúc: <span className="font-black text-emerald-600">{lastSubmission.time}</span>
                    </p>
                  </div>
                </div>
              )}

              {errorMessage && (
                <div className="bg-red-50 border border-red-100 rounded-xl p-4 flex items-start gap-3 animate-in slide-in-from-top-2 fade-in duration-400 shadow-sm text-left">
                  <AlertCircle className="text-red-500 w-5 h-5 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs font-bold text-red-900">Gửi thất bại!</p>
                    <p className="text-[11px] text-red-700/80 leading-snug">{errorMessage}</p>
                  </div>
                </div>
              )}

              <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="group relative w-full overflow-hidden py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-black text-sm rounded-xl shadow-lg shadow-indigo-100 transition-all duration-300 active:scale-[0.98]"
              >
                <div className="relative z-10 flex items-center justify-center gap-2">
                  {isSubmitting ? (
                    <div className="w-5 h-5 border-[3px] border-white/30 border-t-white rounded-full animate-spin" />
                  ) : (
                    <>
                      <Send className="w-4 h-4 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
                      XÁC NHẬN CHẤM CÔNG
                    </>
                  )}
                </div>
              </button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-2 space-y-5">
          <div className="bg-white rounded-[1.5rem] p-6 shadow-lg shadow-slate-200/50 border border-slate-50 h-full flex flex-col text-left">
            <h3 className="text-lg font-black text-slate-800 mb-5 flex items-center gap-2">
              <History className="w-5 h-5 text-indigo-500" />
              Lịch sử
            </h3>

            <div className="space-y-3 flex-1 overflow-y-auto max-h-[400px] pr-1 custom-scrollbar">
              {logs.length === 0 ? (
                <div className="text-center py-12 opacity-30">
                  <History className="text-slate-300 w-10 h-10 mx-auto mb-2" />
                  <p className="text-[11px] font-bold text-slate-400">Trống</p>
                </div>
              ) : (
                logs.map((log) => (
                  <div key={log.id} className="p-3.5 rounded-xl bg-slate-50 border border-slate-100 hover:border-indigo-100 hover:bg-white transition-all duration-300 animate-in fade-in slide-in-from-right-4 shadow-sm">
                    <div className="flex justify-between items-center mb-2">
                      <div className={`flex items-center gap-1.5 px-2 py-0.5 rounded-md ${log.typeCheckInOut === CheckType.IN ? 'bg-indigo-50 text-indigo-700' : 'bg-amber-50 text-amber-700'}`}>
                        <div className={`w-1.5 h-1.5 rounded-full ${log.typeCheckInOut === CheckType.IN ? 'bg-indigo-500' : 'bg-amber-500'}`} />
                        <span className="text-[9px] font-black uppercase tracking-tighter">
                          {log.typeCheckInOut === CheckType.IN ? 'Check-in' : 'Check-out'}
                        </span>
                      </div>
                      <span className="text-[9px] text-slate-400 font-bold">
                        {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true })}
                      </span>
                    </div>
                    <p className="text-xs font-bold text-slate-700 font-mono tracking-tighter truncate">{log.dateCheckInOut}</p>
                  </div>
                ))
              )}
            </div>

            <div className="mt-6 pt-6 border-t border-slate-100">
               <div className="flex items-center gap-2 mb-3">
                 <Globe className="w-3 h-3 text-slate-400" />
                 <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Trạng thái API</h4>
               </div>
               <div className="grid grid-cols-1 gap-2">
                 <div className="px-3 py-2 rounded-lg bg-slate-50 flex justify-between items-center border border-slate-100 overflow-hidden">
                    <span className="text-[9px] font-bold text-slate-500 uppercase flex-shrink-0">DOMAIN</span>
                    <span className="text-[9px] font-black uppercase text-indigo-500 truncate ml-2" title={apiDomain}>
                      {apiDomain || "Chưa thiết lập"}
                    </span>
                 </div>
                 <div className="px-3 py-2 rounded-lg bg-slate-50 flex justify-between items-center border border-slate-100">
                    <span className="text-[9px] font-bold text-slate-500 uppercase">Cấu hình</span>
                    <span className={`text-[9px] font-black uppercase ${basicAuth && accessToken ? 'text-emerald-500' : 'text-amber-500'}`}>
                      {basicAuth && accessToken ? 'Đã sẵn sàng' : 'Cần thiết lập'}
                    </span>
                 </div>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

