import React, { useState, useEffect } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send, Clock, Settings, X, Save, ShieldCheck, Globe, Link, AlertCircle } from 'lucide-react';
import { CheckType, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  username: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, username, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [apiDomain, setApiDomain] = useState('');
  const [basicAuth, setBasicAuth] = useState('');
  const [accessToken, setAccessToken] = useState('');

  const API_PATH = '/apietms/api/ChechInData/MobileAddCheckInOut';

  useEffect(() => {
    const savedDomain = localStorage.getItem('sync_api_domain') || '';
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setApiDomain(savedDomain);
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_api_domain', apiDomain);
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
  };

  const handleSubmit = async () => {
    if (!apiDomain || !basicAuth || !accessToken) {
      setErrorMessage("Vui lòng vào phần Cài đặt để cấu hình Domain, Basic Auth và Token!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    setLastSubmission(null);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    const cleanDomain = apiDomain.replace(/^https?:\/\//, '').replace(/\/$/, '');
    const targetUrl = `https://${cleanDomain}${API_PATH}`;

    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
    });

    const fullUrl = `${targetUrl}?${params.toString()}`;

    try {
      console.log("[REQUEST]:", fullUrl);

      const response = await fetch(fullUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken,
          'Accept': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Lỗi máy chủ hoặc cấu hình.`);
      }

      const result = await response.json();

      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 10));
        setLastSubmission({ time: randomTime, type });
      } else {
        throw new Error(result.message || "Máy chủ từ chối yêu cầu.");
      }
    } catch (error) {
      console.error("API Error:", error);
      let msg = error instanceof Error ? error.message : "Đã có lỗi xảy ra.";
      if (msg === "Failed to fetch") {
        msg = "Lỗi CORS: Trình duyệt chặn request trực tiếp đến domain khác. Điều này xảy ra khi deploy lên Vercel. Bạn cần cấu hình server API cho phép CORS hoặc sử dụng giải pháp proxy phía server.";
      }
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-3xl flex flex-col gap-5 animate-in fade-in slide-in-from-bottom-8 duration-700 ease-out relative">

      {/* Settings Modal */}
      {isSettingsOpen && (
