import React, { useState, useEffect } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send, Clock, Settings, X, Save, ShieldCheck, Globe, AlertCircle } from 'lucide-react';
import { CheckType, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  username: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, username, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [basicAuth, setBasicAuth] = useState('');
  const [accessToken, setAccessToken] = useState('');

  // Fixed API endpoint through proxy
  const API_DOMAIN = 'ddc.fis.vn';
  const PROXY_PATH = '/api-proxy/apietms/api/ChechInData/MobileAddCheckInOut';

  useEffect(() => {
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
  };

  const handleSubmit = async () => {
    if (!basicAuth || !accessToken) {
      setErrorMessage("Vui lòng vào phần Cài đặt để cấu hình Basic Auth và Token!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    setLastSubmission(null);

    const randomTime = generateRandomTime(type);
    const formattedDate = formatPayloadDate(selectedDate, randomTime);

    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
    });

    const fullUrl = `${PROXY_PATH}?${params.toString()}`;

    try {
      console.log("[PROXY REQUEST]:", fullUrl);

      const response = await fetch(fullUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken,
          'Accept': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Lỗi máy chủ hoặc cấu hình proxy.`);
      }

      const result = await response.json();

      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 10));
        setLastSubmission({ time: randomTime, type });
      } else {
        throw new Error(result.message || "Máy chủ phản hồi thất bại.");
      }
    } catch (error) {
      console.error("API Error:", error);
      let msg = error instanceof Error ? error.message : "Đã có lỗi xảy ra.";
      if (msg === "Failed to fetch") {
        msg = "Lỗi kết nối hoặc Proxy chưa sẵn sàng. Hãy đảm bảo bạn đã deploy đúng file vercel.json.";
      }
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-3xl flex flex-col gap-5 animate-in fade-in slide-in-from-bottom-8 duration-700 ease-out relative">

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl p-8 border border-slate-100 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-6">
              <div>
                <h3 className="text-xl font-black text-slate-800 flex items-center gap-2">
                  <Settings className="w-6 h-6 text-indigo-600" />
                  Cấu hình Auth
                </h3>
              </div>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>

            <div className="space-y-5 text-left">
              <div className="p-4 bg-indigo-50 rounded-2xl border border-indigo-100 mb-2">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">DOMAIN MẶC ĐỊNH</p>
                <p className="text-sm font-bold text-indigo-700 font-mono">{API_DOMAIN}</p>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">AUTHORIZATION (BASIC)</label>
                <input
                  type="password"
                  placeholder="Basic c3NkX2F..."
                  value={basicAuth}
                  onChange={(e) => setBasicAuth(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono text-xs"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ACCESS TOKEN</label>
                <textarea
                  placeholder="Nhập token hệ thống..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-4 py-3.5 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono text-xs h-32 resize-none"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 transition-all active:scale-95 flex items-center justify-center gap-2"
              >
                <Save className="w-4 h-4" />
                LƯU CẤU HÌNH
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Profile Card */}
      <div className="flex flex-col md:flex-row items-center justify-between bg-white rounded-2xl p-4 shadow-lg border border-slate-50 gap-4">
        <div className="flex items-center gap-3">
          <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-100">
            <User className="text-white w-6 h-6" />
          </div>
          <div className="text-left">
            <h2 className="text-lg font-black text-slate-800 leading-tight">{username}</h2>
            <div className="flex items-center gap-1.5">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Mã NV:</span>
              <span className="text-[11px] font-black text-indigo-600">{userID}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"
            title="Cài đặt Auth"
          >
            <Settings className="w-5 h-5" />
          </button>
          <div className="w-px h-6 bg-slate-100 mx-1"></div>
          <button 
            onClick={onLogout}
            className="px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 text-sm font-bold rounded-xl transition-all"
          >
            <LogOut className="w-4 h-4" />
            Thoát
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-5">
        <div className="lg:col-span-3 space-y-5">
          <div className="bg-white rounded-3xl p-6 shadow-xl border border-slate-50 text-left">
            <h3 className="text-xl font-black text-slate-800 mb-6 flex items-center gap-2">
              <Clock className="w-6 h-6 text-indigo-600" />
              Chấm công Proxy
            </h3>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 ml-1 uppercase tracking-wide">Ngày thực hiện</label>
                <div className="relative group overflow-hidden">
                  <div className="bg-slate-50 border-2 border-slate-100 group-hover:border-indigo-400 rounded-2xl p-4 flex items-center transition-all cursor-pointer">
                    <Calendar className="w-6 h-6 text-indigo-500 mr-4" />
                    <div className="flex flex-col">
                      <span className="text-xs text-slate-400 font-bold uppercase mb-0.5">Lịch trình</span>
                      <span className="text-lg font-black text-slate-800">{displayDate()}</span>
                    </div>
                  </div>
                  <input 
                    type="date"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    className="absolute inset-0 opacity-0 cursor-pointer"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 ml-1 uppercase tracking-wide">Ghi nhận</label>
                <div className="relative flex p-1.5 bg-slate-100 rounded-2xl border border-slate-200">
                  <div 
                    className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-white rounded-xl shadow-md transition-all duration-300 ease-out ${
                      type === CheckType.OUT ? 'translate-x-full' : 'translate-x-0'
                    }`}
                  />
                  <button
                    onClick={() => setType(CheckType.IN)}
                    className={`relative z-10 flex-1 py-3 rounded-xl font-black text-sm transition-colors ${
                      type === CheckType.IN ? 'text-indigo-600' : 'text-slate-400'
                    }`}
                  >
                    VÀO CA (IN)
                  </button>
                  <button
                    onClick={() => setType(CheckType.OUT)}
                    className={`relative z-10 flex-1 py-3 rounded-xl font-black text-sm transition-colors ${
                      type === CheckType.OUT ? 'text-indigo-600' : 'text-slate-400'
                    }`}
                  >
