import React, { useState, useEffect, useMemo } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send, Clock, Settings, X, Save, AlertCircle } from 'lucide-react';
import { CheckType, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  username: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, username, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [basicAuth, setBasicAuth] = useState('');
  const [accessToken, setAccessToken] = useState('');

  // Generate preview times for both IN and OUT
  const sampleTimes = useMemo(() => ({
    in: generateRandomTime(CheckType.IN),
    out: generateRandomTime(CheckType.OUT)
  }), [selectedDate, lastSubmission]);

  // The actual time that will be used for the current submission
  const currentTimeToSubmit = useMemo(() => {
    return type === CheckType.IN ? sampleTimes.in : sampleTimes.out;
  }, [type, sampleTimes]);

  const PROXY_PATH = '/api-proxy/apietms/api/ChechInData/MobileAddCheckInOut';

  useEffect(() => {
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
  };

  const handleSubmit = async () => {
    if (!basicAuth || !accessToken) {
      setErrorMessage("Vui lòng vào phần Cài đặt để cấu hình Basic Auth và Token!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    setLastSubmission(null);

    const timeToSend = currentTimeToSubmit;
    const formattedDate = formatPayloadDate(selectedDate, timeToSend);

    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
    });

    const fullUrl = `${PROXY_PATH}?${params.toString()}`;

    try {
      const response = await fetch(fullUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken,
          'Accept': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Lỗi máy chủ hoặc cấu hình proxy.`);
      }

      const result = await response.json();

      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 10));
        setLastSubmission({ time: timeToSend, type });
      } else {
        throw new Error(result.message || "Máy chủ phản hồi thất bại.");
      }
    } catch (error) {
      console.error("API Error:", error);
      let msg = error instanceof Error ? error.message : "Đã có lỗi xảy ra.";
      if (msg === "Failed to fetch") {
        msg = "Lỗi kết nối. Hãy đảm bảo bạn đã deploy đúng file vercel.json.";
      }
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-4xl flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-8 border border-slate-100 overflow-hidden">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Settings className="w-5 h-5 text-indigo-500" />
                Cài đặt Auth
              </h3>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>

            <div className="space-y-4 text-left">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">AUTHORIZATION (BASIC)</label>
                <input
                  type="password"
                  placeholder="Basic c3NkX2F..."
                  value={basicAuth}
                  onChange={(e) => setBasicAuth(e.target.value)}
                  className="w-full px-4 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 font-mono text-xs transition-all"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">ACCESS TOKEN</label>
                <textarea
                  placeholder="Nhập token..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-4 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 font-mono text-xs h-32 resize-none transition-all"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-200 transition-all active:scale-[0.98] flex items-center justify-center gap-2"
              >
                <Save className="w-4 h-4" />
                LƯU CẤU HÌNH
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header Profile Card */}
      <div className="bg-white rounded-2xl px-6 py-4 shadow-sm border border-slate-100 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-indigo-100 rounded-xl flex items-center justify-center">
            <User className="text-indigo-600 w-6 h-6" />
          </div>
          <div className="text-left">
            <h2 className="text-lg font-bold text-slate-800 leading-tight">{username}</h2>
            <div className="flex items-center gap-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Mã NV:</span>
              <span className="text-[11px] font-bold text-indigo-600">{userID}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2 text-slate-400 hover:text-indigo-600 transition-colors"
          >
            <Settings className="w-5 h-5" />
          </button>
          <div className="w-px h-8 bg-slate-100"></div>
          <button 
            onClick={onLogout}
            className="flex items-center gap-2 text-slate-500 hover:text-red-500 transition-colors px-2"
          >
            <LogOut className="w-4 h-4" />
            <span className="text-xs font-bold uppercase tracking-wider">Thoát</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
        {/* Left Card: Chấm công ngẫu nhiên */}
        <div className="bg-white rounded-[2rem] p-8 shadow-md border border-slate-50 flex flex-col gap-6 text-left relative">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center">
              <Clock className="w-5 h-5 text-indigo-600" />
            </div>
            <h3 className="text-lg font-bold text-slate-800">Chấm công ngẫu nhiên</h3>
          </div>

          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Ngày thực hiện</label>
              <div className="relative group">
                <div className="bg-[#f8fbfe] border border-slate-100 group-hover:border-indigo-200 rounded-2xl p-4 flex items-center gap-4 transition-all">
                  <Calendar className="w-6 h-6 text-indigo-500" />
                  <div className="flex flex-col">
                    <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Lịch trình</span>
                    <span className="text-xl font-bold text-slate-700">{displayDate()}</span>
                  </div>
                </div>
                <input 
