                    type === CheckType.OUT ? 'text-indigo-600' : 'text-slate-400'
                  }`}
                >
                  Check-out
                </button>
              </div>
            </div>

            {lastSubmission && (
              <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-4 flex items-start gap-3 animate-in zoom-in-95">
                <CheckCircle2 className="text-emerald-500 w-5 h-5 mt-0.5" />
                <div>
                  <p className="text-sm font-bold text-emerald-900 leading-tight">Ghi nhận thành công</p>
                  <p className="text-xs text-emerald-700 mt-0.5">Mốc giờ gửi: <span className="font-bold">{lastSubmission.time}</span></p>
                </div>
