                  }`}
                />
                <button
                  onClick={() => setType(CheckType.IN)}
                  className={`relative z-10 flex-1 py-3.5 rounded-xl font-bold text-sm transition-colors ${
                    type === CheckType.IN ? 'text-amber-700' : 'text-amber-400'
                  }`}
                >
                  Check-in
                </button>
                <button
                  onClick={() => setType(CheckType.OUT)}
                  className={`relative z-10 flex-1 py-3.5 rounded-xl font-bold text-sm transition-colors ${
                    type === CheckType.OUT ? 'text-amber-700' : 'text-amber-400'
                  }`}
                >
                  Check-out
                </button>
              </div>
            </div>

            {lastSubmission && (
              <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-4 flex items-start gap-3 animate-in zoom-in-95">
                <CheckCircle2 className="text-emerald-500 w-5 h-5 mt-0.5" />
                <div>
                  <p className="text-sm font-bold text-emerald-900 leading-tight">Cày thành công một cuốc!</p>
                  <p className="text-xs text-emerald-700 mt-0.5">Giờ đẹp đã chọn: <span className="font-bold">{lastSubmission.time}</span></p>
                </div>
              </div>
            )}

            {errorMessage && (
              <div className="bg-red-50 border border-red-100 rounded-2xl p-4 flex items-start gap-3 animate-in slide-in-from-top-2">
                <AlertCircle className="text-red-500 w-5 h-5 mt-0.5" />
                <div className="flex-1">
                  <p className="text-sm font-bold text-red-900 leading-tight">Sự cố cày bừa</p>
                  <p className="text-[10px] text-red-700 mt-0.5 leading-snug">{errorMessage}</p>
                </div>
              </div>
            )}

            <button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full py-5 bg-amber-600/90 hover:bg-amber-600 disabled:bg-slate-200 disabled:text-slate-400 text-white font-bold rounded-2xl shadow-xl shadow-amber-100 transition-all flex items-center justify-center gap-3 active:scale-[0.97]"
            >
              {isSubmitting ? (
                <div className="w-6 h-6 border-3 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  CHỐT ĐƠN ĐI CÀY
                </>
              )}
            </button>
          </div>
        </div>

        {/* Right Card: Nhật ký cày cuốc */}
        <div className="bg-white rounded-[2rem] shadow-md border border-slate-50 flex flex-col h-full text-left overflow-hidden relative">
          <div className="p-8 pb-4 flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-amber-50 flex items-center justify-center">
              <History className="w-5 h-5 text-amber-600" />
            </div>
            <h3 className="text-lg font-bold text-slate-800">Nhật ký cày cuốc</h3>
          </div>

          <div className="flex-1 overflow-y-auto px-8 py-4 custom-scrollbar min-h-[350px] pb-32">
            {logs.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-24 text-slate-300 gap-3">
                <History className="w-12 h-12 stroke-[1.5]" />
                <p className="text-[11px] font-bold uppercase tracking-widest">Chưa cày được gì</p>
              </div>
            ) : (
              <div className="space-y-3">
                {logs.map((log) => (
                  <div key={log.id} className="p-4 rounded-2xl bg-[#fffcf5] border border-amber-50 flex items-center justify-between hover:border-amber-100 transition-all">
                    <div className="flex flex-col gap-0.5">
                      <span className={`text-[10px] font-bold tracking-widest ${log.typeCheckInOut === CheckType.IN ? 'text-amber-600' : 'text-orange-600'}`}>
                        {log.typeCheckInOut === CheckType.IN ? 'CHECK-IN' : 'CHECK-OUT'}
                      </span>
                      <p className="text-sm font-bold text-slate-700 font-mono">{log.dateCheckInOut}</p>
                    </div>
                    <span className="text-[10px] text-slate-400 font-bold bg-white px-2 py-1 rounded-lg border border-slate-100">
                      {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Gieo quẻ giờ cày - Hiển thị rõ ràng dải giờ */}
          <div className="absolute bottom-6 right-8 left-8 bg-white border border-amber-100 shadow-xl rounded-2xl p-4 flex flex-col gap-2 z-10">
            <div className="flex items-center justify-between border-b border-amber-50 pb-2 mb-1">
              <span className="text-[10px] font-bold text-amber-800 uppercase tracking-widest">Gieo quẻ giờ cày</span>
              <Clock className="w-3.5 h-3.5 text-amber-500" />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-1">
                <div className="flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div>
                  <span className="text-[9px] font-bold text-amber-600 uppercase">Check-in</span>
                </div>
                <div className="flex flex-col pl-3">
                  <span className="text-[9px] text-slate-400 font-bold">Dải: 08:13 - 08:29</span>
                  <span className="text-sm font-black text-amber-600 font-mono">{sampleTimes.in}</span>
                </div>
              </div>

              <div className="flex flex-col gap-1">
                <div className="flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div>
                  <span className="text-[9px] font-bold text-orange-600 uppercase">Check-out</span>
                </div>
                <div className="flex flex-col pl-3">
