                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send, Clock, Settings, X, Save, AlertCircle } from 'lucide-react';
import { CheckType, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  username: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, username, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [basicAuth, setBasicAuth] = useState('');
  const [accessToken, setAccessToken] = useState('');

  const dateInputRef = useRef<HTMLInputElement>(null);

  // Gieo quẻ giờ cày cho cả IN và OUT
  const sampleTimes = useMemo(() => ({
    in: generateRandomTime(CheckType.IN),
    out: generateRandomTime(CheckType.OUT)
  }), [selectedDate, lastSubmission]);

  const currentTimeToSubmit = useMemo(() => {
    return type === CheckType.IN ? sampleTimes.in : sampleTimes.out;
  }, [type, sampleTimes]);

  const PROXY_PATH = '/api-proxy/apietms/api/ChechInData/MobileAddCheckInOut';

  useEffect(() => {
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
  };

  // Hàm trigger mở date picker triệt để
  const handleOpenDatePicker = () => {
    if (dateInputRef.current) {
      try {
        // Sử dụng API showPicker() mới nhất
        if (typeof (dateInputRef.current as any).showPicker === 'function') {
          (dateInputRef.current as any).showPicker();
        } else {
          // Fallback cho các trình duyệt cũ hơn
          dateInputRef.current.click();
        }
      } catch (error) {
        console.error("Failed to open date picker:", error);
        // Fallback cuối cùng
        dateInputRef.current.focus();
        dateInputRef.current.click();
      }
    }
  };

  const handleSubmit = async () => {
    if (!basicAuth || !accessToken) {
      setErrorMessage("Chưa cấu hình 'sức mạnh' (Auth/Token), không thể đi cày!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    setLastSubmission(null);

    const timeToSend = currentTimeToSubmit;
    const formattedDate = formatPayloadDate(selectedDate, timeToSend);

    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
    });

    const fullUrl = `${PROXY_PATH}?${params.toString()}`;

    try {
      const response = await fetch(fullUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken,
          'Accept': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Máy chủ không cho đi cày.`);
      }

      const result = await response.json();

      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 10));
        setLastSubmission({ time: timeToSend, type });
      } else {
        throw new Error(result.message || "Ghi nhận công sức thất bại.");
      }
    } catch (error) {
      console.error("API Error:", error);
      let msg = error instanceof Error ? error.message : "Xảy ra sự cố cày bừa.";
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-4xl flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Cấu hình sức mạnh Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-8 border border-slate-100 overflow-hidden">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Settings className="w-5 h-5 text-amber-500" />
                Cấu hình sức mạnh
              </h3>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>

            <div className="space-y-4 text-left">
              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">BASIC AUTH (LÁ CHẮN)</label>
                <input
                  type="password"
                  placeholder="Basic c3NkX2F..."
                  value={basicAuth}
                  onChange={(e) => setBasicAuth(e.target.value)}
                  className="w-full px-4 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-amber-500/20 focus:border-amber-500 font-mono text-xs transition-all"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">ACCESS TOKEN (SỨC MẠNH)</label>
                <textarea
                  placeholder="Nhập token cày thuê..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-4 py-3 rounded-2xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-amber-500/20 focus:border-amber-500 font-mono text-xs h-32 resize-none transition-all"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-4 bg-amber-600 hover:bg-amber-700 text-white font-bold rounded-2xl shadow-lg shadow-amber-200 transition-all active:scale-[0.98] flex items-center justify-center gap-2"
              >
                <Save className="w-4 h-4" />
                LƯU CẤU HÌNH
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header Profile Card */}
      <div className="bg-white rounded-2xl px-6 py-4 shadow-sm border border-slate-100 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-amber-100 rounded-xl flex items-center justify-center">
            <User className="text-amber-600 w-6 h-6" />
          </div>
          <div className="text-left">
            <h2 className="text-lg font-bold text-slate-800 leading-tight">Con bò: {username}</h2>
            <div className="flex items-center gap-1">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Mã số cày cuốc:</span>
              <span className="text-[11px] font-bold text-amber-600">{userID}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="p-2 text-slate-400 hover:text-amber-600 transition-colors"
          >
            <Settings className="w-5 h-5" />
          </button>
          <div className="w-px h-8 bg-slate-100"></div>
          <button 
            onClick={onLogout}
            className="flex items-center gap-2 text-slate-500 hover:text-red-500 transition-colors px-2"
          >
            <LogOut className="w-4 h-4" />
            <span className="text-xs font-bold uppercase tracking-wider">Về chuồng</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
        {/* Left Card: Xổ số giờ cày */}
        <div className="bg-white rounded-[2rem] p-8 shadow-md border border-slate-50 flex flex-col gap-6 text-left relative">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-amber-50 flex items-center justify-center">
              <Clock className="w-5 h-5 text-amber-600" />
            </div>
            <h3 className="text-lg font-bold text-slate-800">Xổ số giờ cày</h3>
          </div>

          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Hôm nay cày ngày mấy?</label>
              <div 
                className="relative group cursor-pointer" 
                onClick={handleOpenDatePicker}
              >
                {/* Pointer-events-none đảm bảo sự kiện click luôn đi thẳng vào lớp cha xử lý */}
                <div className="bg-[#fffbeb] border border-amber-100 group-hover:border-amber-200 rounded-2xl p-4 flex items-center gap-4 transition-all active:bg-amber-50 pointer-events-none">
                  <Calendar className="w-6 h-6 text-amber-500" />
                  <div className="flex flex-col">
                    <span className="text-[10px] text-amber-400 font-bold uppercase tracking-widest">Lịch cày bừa</span>
                    <span className="text-xl font-bold text-slate-700">{displayDate()}</span>
                  </div>
                </div>
                {/* Input ẩn phục vụ trigger */}
                <input 
                  ref={dateInputRef}
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="absolute inset-0 w-full h-full opacity-0 pointer-events-none"
                  style={{ visibility: 'visible' }}
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">Trạng thái cày</label>
              <div className="relative flex p-1 bg-[#fef3c7] rounded-2xl border border-amber-100">
                <div 
                  className={`absolute top-1 bottom-1 w-[calc(50%-4px)] bg-white rounded-xl shadow-sm transition-all duration-300 ease-out ${
                    type === CheckType.OUT ? 'translate-x-full' : 'translate-x-0'
                  }`}
                />
                <button
                  onClick={() => setType(CheckType.IN)}
                  className={`relative z-10 flex-1 py-3.5 rounded-xl font-bold text-sm transition-colors ${
                    type === CheckType.IN ? 'text-amber-700' : 'text-amber-400'
                  }`}
                >
                  Check-in
                </button>
                <button
                  onClick={() => setType(CheckType.OUT)}
                  className={`relative z-10 flex-1 py-3.5 rounded-xl font-bold text-sm transition-colors ${
                    type === CheckType.OUT ? 'text-amber-700' : 'text-amber-400'
                  }`}
                >
                  Check-out
                </button>
              </div>
            </div>

            {lastSubmission && (
              <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-4 flex items-start gap-3 animate-in zoom-in-95">
                <CheckCircle2 className="text-emerald-500 w-5 h-5 mt-0.5" />
                <div>
                  <p className="text-sm font-bold text-emerald-900 leading-tight">Cày thành công một cuốc!</p>
                  <p className="text-xs text-emerald-700 mt-0.5">Giờ đẹp đã chọn: <span className="font-bold">{lastSubmission.time}</span></p>
                </div>
              </div>
            )}

            {errorMessage && (
              <div className="bg-red-50 border border-red-100 rounded-2xl p-4 flex items-start gap-3 animate-in slide-in-from-top-2">
                <AlertCircle className="text-red-500 w-5 h-5 mt-0.5" />
                <div className="flex-1">
                  <p className="text-sm font-bold text-red-900 leading-tight">Sự cố cày bừa</p>
                  <p className="text-[10px] text-red-700 mt-0.5 leading-snug">{errorMessage}</p>
                </div>
              </div>
            )}

            <button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full py-5 bg-amber-600/90 hover:bg-amber-600 disabled:bg-slate-200 disabled:text-slate-400 text-white font-bold rounded-2xl shadow-xl shadow-amber-100 transition-all flex items-center justify-center gap-3 active:scale-[0.97]"
            >
              {isSubmitting ? (
                <div className="w-6 h-6 border-3 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <Send className="w-5 h-5" />
                  CHỐT ĐƠN ĐI CÀY
                </>
              )}
            </button>
          </div>
        </div>

        {/* Right Card: Nhật ký cày cuốc */}
        <div className="bg-white rounded-[2rem] shadow-md border border-slate-50 flex flex-col h-full text-left overflow-hidden relative">
          <div className="p-8 pb-4 flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-amber-50 flex items-center justify-center">
              <History className="w-5 h-5 text-amber-600" />
            </div>
            <h3 className="text-lg font-bold text-slate-800">Nhật ký cày cuốc</h3>
          </div>

          <div className="flex-1 overflow-y-auto px-8 py-4 custom-scrollbar min-h-[350px] pb-32">
            {logs.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-24 text-slate-300 gap-3">
                <History className="w-12 h-12 stroke-[1.5]" />
                <p className="text-[11px] font-bold uppercase tracking-widest">Chưa cày được gì</p>
              </div>
            ) : (
              <div className="space-y-3">
                {logs.map((log) => (
                  <div key={log.id} className="p-4 rounded-2xl bg-[#fffcf5] border border-amber-50 flex items-center justify-between hover:border-amber-100 transition-all">
                    <div className="flex flex-col gap-0.5">
                      <span className={`text-[10px] font-bold tracking-widest ${log.typeCheckInOut === CheckType.IN ? 'text-amber-600' : 'text-orange-600'}`}>
                        {log.typeCheckInOut === CheckType.IN ? 'CHECK-IN' : 'CHECK-OUT'}
                      </span>
                      <p className="text-sm font-bold text-slate-700 font-mono">{log.dateCheckInOut}</p>
                    </div>
                    <span className="text-[10px] text-slate-400 font-bold bg-white px-2 py-1 rounded-lg border border-slate-100">
                      {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>

