import React, { useState, useEffect, useMemo } from 'react';
import { User, LogOut, Calendar, CheckCircle2, History, Send, Clock, Settings, X, Save, AlertCircle } from 'lucide-react';
import { CheckType, LogEntry } from '../types';
import { generateRandomTime, formatPayloadDate, getTodayString } from '../utils';

interface DashboardProps {
  userID: string;
  username: string;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ userID, username, onLogout }) => {
  const [selectedDate, setSelectedDate] = useState(getTodayString());
  const [type, setType] = useState<CheckType>(CheckType.IN);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [lastSubmission, setLastSubmission] = useState<{ time: string; type: CheckType } | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [basicAuth, setBasicAuth] = useState('');
  const [accessToken, setAccessToken] = useState('');

  const sampleTimes = useMemo(() => ({
    in: generateRandomTime(CheckType.IN),
    out: generateRandomTime(CheckType.OUT)
  }), [selectedDate, lastSubmission]);

  const currentTimeToSubmit = useMemo(() => {
    return type === CheckType.IN ? sampleTimes.in : sampleTimes.out;
  }, [type, sampleTimes]);

  const PROXY_PATH = '/api-proxy/apietms/api/ChechInData/MobileAddCheckInOut';

  useEffect(() => {
    const savedBasic = localStorage.getItem('sync_basic_auth') || '';
    const savedToken = localStorage.getItem('sync_access_token') || '';
    setBasicAuth(savedBasic);
    setAccessToken(savedToken);
  }, []);

  const saveSettings = () => {
    localStorage.setItem('sync_basic_auth', basicAuth);
    localStorage.setItem('sync_access_token', accessToken);
    setIsSettingsOpen(false);
  };

  const handleSubmit = async () => {
    if (!basicAuth || !accessToken) {
      setErrorMessage("Chưa cấu hình 'sức mạnh' (Auth/Token), không thể đi cày!");
      setIsSettingsOpen(true);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);
    setLastSubmission(null);

    const timeToSend = currentTimeToSubmit;
    const formattedDate = formatPayloadDate(selectedDate, timeToSend);

    const params = new URLSearchParams({
      userId: userID,
      typeCheckInOut: type.toString(),
      dateCheckInOut: formattedDate
    });

    const fullUrl = `${PROXY_PATH}?${params.toString()}`;

    try {
      const response = await fetch(fullUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Basic ${basicAuth}`,
          'username': username,
          'token': accessToken,
          'Accept': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Máy chủ không cho đi cày.`);
      }

      const result = await response.json();

      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 10));
        setLastSubmission({ time: timeToSend, type });
      } else {
        throw new Error(result.message || "Ghi nhận công sức thất bại.");
      }
    } catch (error) {
      console.error("API Error:", error);
      let msg = error instanceof Error ? error.message : "Xảy ra sự cố cày bừa.";
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-md flex flex-col gap-5 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-[340px] rounded-[2rem] shadow-2xl p-7 border border-slate-100 overflow-hidden text-left">
            <div className="flex justify-between items-center mb-5">
              <h3 className="text-base font-bold text-slate-800 flex items-center gap-2 uppercase">
                <Settings className="w-5 h-5 text-amber-500" />
                Sức mạnh
              </h3>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-5 h-5 text-slate-400" />
              </button>
            </div>

            <div className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-[13px] font-bold text-slate-400 uppercase tracking-widest ml-1">BASIC AUTH</label>
                <input
                  type="password"
                  placeholder="Basic c3NkX2F..."
                  value={basicAuth}
                  onChange={(e) => setBasicAuth(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none font-mono text-[13px]"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[13px] font-bold text-slate-400 uppercase tracking-widest ml-1">TOKEN</label>
                <textarea
                  placeholder="Token cày thuê..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none font-mono text-[13px] h-24 resize-none"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-4 bg-amber-600 text-white text-[14px] font-bold rounded-xl shadow-lg shadow-amber-100 uppercase tracking-wider active:scale-95 transition-transform"
              >
                Lưu cấu hình
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Profile Header */}
      <div className="bg-white rounded-[2.5rem] p-5 shadow-sm border border-slate-100 flex items-center justify-between gap-3">
        <div className="flex items-center gap-4 min-w-0">
          <div className="w-14 h-14 bg-amber-50 rounded-2xl flex items-center justify-center border border-amber-100 shadow-inner flex-shrink-0">
            <User className="text-amber-600 w-7 h-7" />
          </div>
          <div className="text-left min-w-0 flex flex-col justify-center">
            <div className="flex items-center gap-2">
              <h2 className="text-[17px] font-bold text-slate-800 truncate leading-none">Con bò: {username}</h2>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1 text-slate-300 hover:text-amber-500">
                <Settings className="w-4.5 h-4.5" />
              </button>
            </div>
            <div className="flex items-center gap-1.5 mt-2">
              <span className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter leading-tight">MÃ SỐ:</span>
              <span className="text-[14px] font-bold text-amber-600 truncate leading-tight uppercase tracking-tight">{userID}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="w-px h-12 bg-slate-100"></div>
          <button 
            onClick={onLogout}
            className="flex flex-col items-center justify-center px-2 py-1 text-slate-400 hover:text-red-500 transition-all"
          >
            <LogOut className="w-5 h-5 rotate-180" />
            <span className="text-[11px] font-bold uppercase tracking-tighter leading-none mt-2">VỀ CHUỒNG</span>
          </button>
        </div>
      </div>

      {/* Control Card */}
      <div className="bg-white rounded-[2.5rem] p-7 shadow-md border border-slate-50 flex flex-col gap-6 text-left">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-amber-50 flex items-center justify-center">
            <Clock className="w-5 h-5 text-amber-600" />
          </div>
          <h3 className="text-[17px] font-bold text-slate-800 uppercase tracking-tight">Xổ số giờ cày</h3>
        </div>

        <div className="space-y-6">
          <div className="space-y-2.5">
            <label className="text-[13px] font-bold text-slate-400 uppercase tracking-widest ml-1">HÔM NAY CÀY NGÀY MẤY?</label>

            <div className="relative overflow-hidden rounded-[1.5rem] group active:scale-[0.98] transition-transform">
              <input 
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="absolute inset-0 w-full h-full opacity-0 z-50 cursor-pointer"
                style={{ fontSize: '16px', colorScheme: 'light' }}
              />
              <div className="bg-[#fffbeb] border border-amber-100 rounded-[1.5rem] p-6 flex items-center gap-5 relative z-0 pointer-events-none group-hover:bg-[#fff7d6] transition-colors">
                <Calendar className="w-8 h-8 text-amber-500" />
                <div className="flex flex-col">
                  <span className="text-[13px] text-amber-400 font-bold uppercase tracking-widest leading-none mb-1.5">Lịch cày bừa</span>
                  <span className="text-3xl font-bold text-slate-700 tracking-tight">{displayDate()}</span>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-2.5">
            <label className="text-[13px] font-bold text-slate-400 uppercase tracking-widest ml-1">TRẠNG THÁI CÀY</label>
            <div className="relative flex p-1.5 bg-[#fef3c7] rounded-2xl border border-amber-50">
              <div 
                className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-white rounded-xl shadow-sm transition-all duration-300 ease-out ${
                  type === CheckType.OUT ? 'translate-x-full' : 'translate-x-0'
                }`}
              />
              <button
                onClick={() => setType(CheckType.IN)}
                className={`relative z-10 flex-1 py-3.5 rounded-xl font-bold text-[15px] transition-colors ${
                  type === CheckType.IN ? 'text-amber-700' : 'text-amber-400'
                }`}
              >
                Check-in
              </button>
              <button
                onClick={() => setType(CheckType.OUT)}
                className={`relative z-10 flex-1 py-3.5 rounded-xl font-bold text-[15px] transition-colors ${
                  type === CheckType.OUT ? 'text-amber-700' : 'text-amber-400'
                }`}
              >
                Check-out
              </button>
            </div>
          </div>

          {lastSubmission && (
            <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-5 flex items-start gap-4 animate-in zoom-in-95">
              <CheckCircle2 className="text-emerald-500 w-6 h-6 mt-0.5" />
              <div>
                <p className="text-[15px] font-bold text-emerald-900 leading-tight">Cày thành công một cuốc!</p>
                <p className="text-[13px] text-emerald-700 mt-1.5">Giờ đẹp: <span className="font-bold underline">{lastSubmission.time}</span></p>
              </div>
            </div>
          )}

          {errorMessage && (
            <div className="bg-red-50 border border-red-100 rounded-2xl p-5 flex items-start gap-4 animate-in slide-in-from-top-2">
              <AlertCircle className="text-red-500 w-6 h-6 mt-0.5" />
              <div className="flex-1">
                <p className="text-[15px] font-bold text-red-900 leading-tight">Sự cố cày bừa</p>
                <p className="text-[13px] text-red-700 mt-1.5 leading-snug">{errorMessage}</p>
