      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: Máy chủ không cho đi cày.`);
      }

      const result = await response.json();

      if (result.resultCode === 1) {
        const newLog: LogEntry = {
          userID,
          typeCheckInOut: type,
          dateCheckInOut: formattedDate,
          id: Math.random().toString(36).substr(2, 9),
          timestamp: Date.now()
        };

        setLogs(prev => [newLog, ...prev].slice(0, 10));
        setLastSubmission({ time: timeToSend, type });
      } else {
        throw new Error(result.message || "Ghi nhận công sức thất bại.");
      }
    } catch (error) {
      console.error("API Error:", error);
      let msg = error instanceof Error ? error.message : "Xảy ra sự cố cày bừa.";
      setErrorMessage(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const displayDate = () => {
    if (!selectedDate) return 'Chọn ngày';
    const parts = selectedDate.split('-');
    if (parts.length !== 3) return selectedDate;
    const [y, m, d] = parts;
    return `${d}-${m}-${y}`;
  };

  return (
    <div className="w-full max-w-6xl flex flex-col gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500 px-4 md:px-0">

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-[400px] rounded-[2.5rem] shadow-2xl p-8 border border-slate-100 overflow-hidden text-left">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2 uppercase">
                <Settings className="w-6 h-6 text-amber-500" />
                Sức mạnh
              </h3>
              <button onClick={() => setIsSettingsOpen(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-6 h-6 text-slate-400" />
              </button>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-400 uppercase tracking-widest ml-1">BASIC AUTH</label>
                <input
                  type="password"
                  placeholder="Basic c3NkX2F..."
                  value={basicAuth}
                  onChange={(e) => setBasicAuth(e.target.value)}
                  className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 focus:outline-none font-mono text-base"
                />
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-slate-400 uppercase tracking-widest ml-1">TOKEN</label>
                <textarea
                  placeholder="Token cày thuê..."
                  value={accessToken}
                  onChange={(e) => setAccessToken(e.target.value)}
                  className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-200 focus:outline-none font-mono text-base h-32 resize-none"
                />
              </div>

              <button
                onClick={saveSettings}
                className="w-full py-5 bg-amber-600 text-white text-base font-bold rounded-2xl shadow-lg shadow-amber-100 uppercase tracking-wider active:scale-95 transition-transform"
              >
                Lưu cấu hình
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Profile Header - Always Full Width */}
      <div className="bg-white rounded-[2.5rem] p-6 shadow-sm border border-slate-100 flex items-center justify-between gap-4">
        <div className="flex items-center gap-5 min-w-0">
          <div className="w-16 h-16 bg-amber-50 rounded-[1.5rem] flex items-center justify-center border border-amber-100 shadow-inner flex-shrink-0">
            <User className="text-amber-600 w-9 h-9" />
          </div>
          <div className="text-left min-w-0 flex flex-col justify-center">
            <div className="flex items-center gap-2.5">
              <h2 className="text-xl md:text-2xl font-bold text-slate-800 truncate leading-none">Con bò: {username}</h2>
              <button onClick={() => setIsSettingsOpen(true)} className="p-1 text-slate-300 hover:text-amber-500 transition-colors">
                <Settings className="w-6 h-6" />
              </button>
            </div>
            <div className="flex items-center gap-2 mt-2.5">
              <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter leading-tight">MÃ SỐ:</span>
              <span className="text-lg font-bold text-amber-600 truncate leading-tight uppercase tracking-tight">{userID}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="w-px h-14 bg-slate-100 hidden md:block"></div>
          <button 
            onClick={onLogout}
            className="flex flex-col items-center justify-center px-4 py-2 text-slate-400 hover:text-red-500 transition-all"
          >
            <LogOut className="w-7 h-7 rotate-180" />
            <span className="text-xs font-bold uppercase tracking-tighter leading-none mt-2.5">VỀ CHUỒNG</span>
          </button>
        </div>
      </div>

      {/* Main Content: Responsive Row/Col Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">

        {/* Left Side: Control Card */}
        <div className="bg-white rounded-[2.5rem] p-8 shadow-md border border-slate-50 flex flex-col gap-8 text-left h-full">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 rounded-full bg-amber-50 flex items-center justify-center border border-amber-100">
              <Clock className="w-6 h-6 text-amber-600" />
            </div>
            <h3 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Xổ số giờ cày</h3>
          </div>

          <div className="space-y-8">
            {/* Date Input */}
            <div className="space-y-3">
              <label className="text-base font-bold text-slate-400 uppercase tracking-widest ml-1">HÔM NAY CÀY NGÀY MẤY?</label>
              <div className="relative overflow-hidden rounded-[2rem] group active:scale-[0.99] transition-transform shadow-sm">
                <input 
                  type="date"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  className="absolute inset-0 w-full h-full opacity-0 z-50 cursor-pointer"
                  style={{ fontSize: '16px', colorScheme: 'light' }}
                />
                <div className="bg-[#fffbeb] border border-amber-100 rounded-[2rem] p-7 flex items-center gap-6 relative z-0 pointer-events-none group-hover:bg-[#fff7d6] transition-colors">
                  <Calendar className="w-10 h-10 text-amber-500" />
                  <div className="flex flex-col">
                    <span className="text-sm text-amber-400 font-bold uppercase tracking-widest leading-none mb-2">Lịch cày bừa</span>
                    <span className="text-4xl font-bold text-slate-700 tracking-tight">{displayDate()}</span>
                  </div>
                </div>
              </div>
            </div>

            {/* Type Selector */}
            <div className="space-y-3">
              <label className="text-base font-bold text-slate-400 uppercase tracking-widest ml-1">TRẠNG THÁI CÀY</label>
              <div className="relative flex p-2 bg-[#fef3c7] rounded-[1.5rem] border border-amber-50 shadow-inner">
