            </div>

            {/* Status Messages */}
            <div className="space-y-4">
              {lastSubmission && (
                <div className="bg-emerald-50 border border-emerald-100 rounded-2xl p-6 flex items-start gap-4 animate-in zoom-in-95 shadow-sm">
                  <CheckCircle2 className="text-emerald-500 w-7 h-7 mt-0.5" />
                  <div>
                    <p className="text-lg font-bold text-emerald-900 leading-tight">Cày thành công một cuốc!</p>
                    <p className="text-base text-emerald-700 mt-2 font-medium">Giờ đẹp: <span className="font-bold underline decoration-2">{lastSubmission.time}</span></p>
                  </div>
                </div>
              )}

              {errorMessage && (
                <div className="bg-red-50 border border-red-100 rounded-2xl p-6 flex items-start gap-4 animate-in slide-in-from-top-2 shadow-sm">
                  <AlertCircle className="text-red-500 w-7 h-7 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-lg font-bold text-red-900 leading-tight">Sự cố cày bừa</p>
                    <p className="text-base text-red-700 mt-2 leading-relaxed font-medium">{errorMessage}</p>
                  </div>
                </div>
              )}
            </div>

            {/* Action Button */}
            <button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full py-6 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 disabled:from-slate-300 disabled:to-slate-300 text-white text-xl font-bold rounded-2xl shadow-2xl shadow-amber-200 uppercase tracking-widest flex items-center justify-center gap-4 active:scale-[0.97] transition-all"
            >
              {isSubmitting ? (
                <div className="w-8 h-8 border-4 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                <>
                  <Send className="w-6 h-6" />
                  Chốt đơn đi cày
                </>
              )}
            </button>
          </div>
        </div>

        {/* Right Side: Logs Card */}
        <div className="flex flex-col gap-6 h-full">
          <div className="bg-white rounded-[2.5rem] shadow-md border border-slate-50 flex flex-col flex-1 text-left overflow-hidden relative min-h-[500px] lg:min-h-0">
            <div className="p-8 pb-4 flex items-center gap-4">
              <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center border border-slate-100">
                <History className="w-6 h-6 text-slate-400" />
              </div>
              <h3 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Nhật ký cày cuốc</h3>
            </div>

            <div className="flex-1 overflow-y-auto px-8 py-4 custom-scrollbar pb-36">
              {logs.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-slate-200 gap-4 opacity-50 py-10">
                  <History className="w-16 h-16 stroke-[1.5]" />
                  <p className="text-base font-bold uppercase tracking-widest">Đang chờ lượt cày</p>
                </div>
              ) : (
                <div className="space-y-4">
                  {logs.map((log) => (
                    <div key={log.id} className="p-6 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-between shadow-sm">
                      <div className="flex flex-col gap-2">
                        <span className={`text-xs font-bold tracking-widest ${log.typeCheckInOut === CheckType.IN ? 'text-amber-600' : 'text-orange-600'}`}>
                          {log.typeCheckInOut === CheckType.IN ? 'CHECK-IN' : 'CHECK-OUT'}
                        </span>
                        <p className="text-xl font-bold text-slate-700 font-mono leading-none tracking-tight">{log.dateCheckInOut}</p>
                      </div>
                      <span className="text-sm text-slate-400 font-bold bg-white px-5 py-2.5 rounded-xl border border-slate-50 shadow-sm">
                        {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Floating Info Box at Bottom of Logs */}
            <div className="absolute bottom-6 right-8 left-8 bg-white/90 backdrop-blur-md border border-amber-100 shadow-2xl rounded-[1.5rem] p-6 flex flex-col gap-4 z-10">
              <div className="flex items-center justify-between border-b border-amber-50 pb-3">
                <span className="text-xs font-bold text-amber-800 uppercase tracking-widest">Quẻ giờ đẹp hôm nay</span>
                <div className="w-3 h-3 bg-amber-400 rounded-full animate-pulse"></div>
              </div>

              <div className="flex justify-between items-center px-2">
                <div className="flex flex-col">
                  <span className="text-2xl font-bold text-slate-700 font-mono tracking-tighter">{sampleTimes.in}</span>
                  <span className="text-[11px] font-bold text-amber-500 uppercase mt-1">Lượt vào</span>
                </div>
                <div className="w-px h-10 bg-slate-100"></div>
                <div className="flex flex-col items-end">
                  <span className="text-2xl font-bold text-slate-700 font-mono tracking-tighter">{sampleTimes.out}</span>
                  <span className="text-[11px] font-bold text-orange-500 uppercase mt-1">Lượt ra</span>
                </div>
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;

