                  <CheckCircle2 className="text-emerald-500 w-4 h-4 md:w-7 md:h-7 mt-0.5" />
                  <div>
                    <p className="text-xs md:text-lg font-bold text-emerald-900 leading-tight">Thành công!</p>
                    <p className="text-[11px] md:text-base text-emerald-700 mt-1 md:mt-2 font-medium">Giờ đẹp: <span className="font-bold underline decoration-2">{lastSubmission.time}</span></p>
                  </div>
                </div>
              )}

              {errorMessage && (
                <div className="bg-red-50 border border-red-100 rounded-xl md:rounded-2xl p-3 md:p-6 flex items-start gap-2.5 md:gap-4 animate-in slide-in-from-top-2">
                  <AlertCircle className="text-red-500 w-4 h-4 md:w-7 md:h-7 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-xs md:text-lg font-bold text-red-900 leading-tight">Sự cố cày bừa</p>
                    <p className="text-[10px] md:text-base text-red-700 mt-1 md:mt-2 leading-snug">{errorMessage}</p>
                  </div>
                </div>
              )}
            </div>

            {/* Action Button */}
            <button
              onClick={handleSubmit}
              disabled={isSubmitting}
              className="w-full py-3.5 md:py-6 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 disabled:from-slate-300 disabled:to-slate-300 text-white text-sm md:text-xl font-bold rounded-xl md:rounded-2xl shadow-lg active:scale-[0.98] transition-all uppercase tracking-widest flex items-center justify-center gap-2 md:gap-4"
            >
              {isSubmitting ? (
                <div className="w-5 h-5 md:w-8 md:h-8 border-4 border-white/30 border-t-white rounded-full animate-spin" />
