        </div>

        {/* Right Side: Logs Card */}
        <div className="bg-white rounded-2xl md:rounded-[2.5rem] shadow-md border border-slate-50 flex flex-col h-full min-h-[320px] md:min-h-[450px] text-left overflow-hidden relative">
