            {logs.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-slate-200 gap-2 md:gap-3 opacity-50 py-6">
                <History className="w-8 h-8 md:w-16 md:h-16 stroke-[1.5]" />
