            <input
              type="text"
              placeholder="Nhập tên của bạn..."
              value={accountName}
              onChange={(e) => setAccountName(e.target.value)}
              className="w-full px-4 py-4 bg-slate-100 border-3 border-slate-900 text-slate-900 focus:outline-none focus:bg-white focus:translate-x-[4px] focus:translate-y-[4px] focus:shadow-none transition-all duration-150 font-bold placeholder:text-slate-400 shadow-[4px_4px_0px_0px_#0f172a]"
              required
            />
          </div>

          <div className="space-y-2 animate-in fade-in slide-in-from-left-4 duration-300 delay-150 fill-mode-both">
            <label className="text-[10px] font-black text-slate-900 uppercase tracking-widest flex items-center gap-2">
              <Shield className="w-3 h-3 stroke-[3px]" /> Mã số nhân viên
            </label>
            <input
              type="text"
              placeholder="Ví dụ: FIS-12345"
              value={inputUserID}
              onChange={(e) => setInputUserID(e.target.value)}
