          >
            {isLoading ? (
              <div className="w-6 h-6 border-4 border-slate-900/20 border-t-slate-900 rounded-full animate-spin" />
            ) : (
              <>
                <span className="text-sm md:text-base uppercase tracking-tight">Bắt đầu cày cuốc</span>
